"""Build CASSIA_supplementary.md: Table S1 from the implementation, S2-S5 (run_v2.py), S5b-S14 and Fig. S1. Run from manuscript/."""
import pandas as pd

R = "../results/v3/"
def md(df):
    cols = list(df.columns)
    out = ["| " + " | ".join(map(str, cols)) + " |", "|" + "---|" * len(cols)]
    for _, r in df.iterrows():
        out.append("| " + " | ".join(f"{v:.3f}" if isinstance(v, float) else str(v).replace("|", "given") for v in r) + " |")
    return "\n".join(out)


INTRO = """All results in this supplement are synthetic (known-truth simulations) or thermodynamic (PHREEQC); none is an empirical result. Every table is regenerated by `scripts/reproduce_all.sh` (manuscript Table 2). Sources by table:

| Tables | Generating script | CSV files |
|---|---|---|
| S1 | `scripts/make_table_s1.py` (from `cassia.simulate.parameter_table()`, CASSIA 0.3.2) | `results/v3/T_S1_simulator_parameters.csv` |
| S2–S5 | `scripts/run_v2.py` | `results/v2/` |
| S5b | `scripts/m2s_family.py` (from `run_v3.py` stage m2s) | `results/v3/T_m2s_family_full.csv` |
| S6–S8, S10 | `scripts/run_v3.py` (stages mlscen, censor, equiv3, chem3) | `results/v3/` |
| S9 | `scripts/seqver_oc.py` | `results/v3/T_seqver_oc.csv` |
| S11–S12 | `scripts/bench_partition.py` | `results/v3/T_bench_partition.csv`, `T_bench_mcse.csv` |
| S13 | `scripts/endpoint_validation.py` | `results/v3/T_endpoint_validation.csv` |
| S14 | `scripts/typeI_validation.py` | `results/v3/T_typeI_validation.csv` |
| Fig. S1 | `scripts/make_supp_figs.py` | `results/v2/ident_profiles.csv` |
"""
base = open("_supp_base_v2.md").read().rstrip()  # Tables S2-S5 from run_v2.py (frozen header/body)
import re
base = re.sub(r"^Tables S1.*$|^All tables are generated.*$", "@@INTRO@@", base, count=1, flags=re.M)
base = base.replace("@@INTRO@@", INTRO)

t1 = pd.read_csv(R + "T_S1_simulator_parameters.csv")
s1 = ("## Table S1. Simulator parameters, distributions, measurement models, evidence-class probabilities and numerical settings (CASSIA 0.3.2)\n\n"
      "Generated from the implementation by `scripts/make_table_s1.py`; a unit test checks that the evidence-class probabilities and "
      "measurement-model constants in this table are those used by the code. LN(m, s): log-normal with log-mean m and log-SD s; "
      "U(a, b): uniform; N(0, s): normal.\n\n" + md(t1) + "\n\n")
a, b = base.index("## Table S1."), base.index("## Table S2.")
base = base[:a] + s1 + base[b:]
F = pd.read_csv(R + "T_m2s_family_full.csv")
F = F[F.target.isin(["q_app_VI", "Ce_VI", "q_tot_aq", "Ce_total"])]
s5b = ("## Table S5b. M2s (exact study-level split conformal) by material family at nominal 90% (10 corpora, outer leave-one-study-out)\n\n"
       "Fraction of test studies with ≥ 90% within-study coverage, with Wilson 95% intervals; mean within-study coverage; fraction of "
       "unbounded intervals (counted as full coverage) and mean width of bounded intervals (log₁₀).\n\n" + md(F) + "\n\n")
a = base.index("## Table S5.")
b = base.find("## Table S6", a)
base = (base[:b] + s5b + base[b:]) if b > 0 else (base.rstrip() + "\n\n" + s5b)
TITLE = open("_v3_front_methods.md").readline()[2:].strip()
base = re.sub(r"^# Supplementary Material for .*$", f'# Supplementary Material for "{TITLE}"', base, count=1, flags=re.M)
S = [base]
m = pd.read_csv(R + "T_mlscen_summary.csv")
m["R²"] = m.apply(lambda r: f"{r['mean']:.3f} ± {r['std']:.3f}", axis=1)
w = m.pivot_table(index=["scenario", "model", "features"], columns="scheme", values="R²", aggfunc="first").reset_index().fillna("–")
S.append("## Table S6. ML validation by mechanism scenario (5 corpora per scenario; R² mean ± SD)\n\n'transfer_from_E': model trained on scenario-E corpora and tested on corpora of the given scenario.\n\n" + md(w))
u = pd.read_csv(R + "T_mlscen_uq.csv")
S.append("**Table S6b.** Study-level coverage of apparent uptake at nominal 90% by scenario (RF, speciation features). mean_cov: mean within-study coverage; frac_ge_0.9: fraction of studies with ≥ 90% coverage; width in log₁₀ units.\n\n" + md(u))
c = pd.read_csv(R + "T_censor_summary.csv")
S.append("## Table S7. Sensitivity to the treatment of negative apparent uptake (RF, LOSO)\n\nn_censored: observations with negative apparent uptake per corpus. 'log_LOD_full': values below LOD set to LOD; 'log_censor_LODhalf': set to LOD/2; 'log_drop_censored': removed; 'asinh_keep_negative': asinh transform without censoring.\n\n" + md(c))
e = pd.read_csv(R + "T_equiv3_summary.csv")
cols = {"sd_rel": "noise", "design": "design", "dof": "ν", "nominal_threshold": "χ²₀.₉₅ nominal", "calibrated_threshold": "calibrated",
        "typeI_nominal": "type-I nominal", "typeI_calibrated_cv": "type-I calibrated (CV)", "power_calibrated|5-30%": "power 5–30%",
        "power_calibrated|>30%": "power >30%", "equivalent|>30%|eps=0.05": "equiv >30% ε=0.05", "equivalent|>30%|eps=0.1": "equiv >30% ε=0.10",
        "inconclusive|>30%|eps=0.1": "inconcl. >30% ε=0.10", "false_equivalence|eps=0.05": "false equiv ε=0.05",
        "false_equivalence|eps=0.1": "false equiv ε=0.10", "equivalence_power|eps=0.1": "equiv power ε=0.10",
        "high_red_truly_within|eps=0.1": "truly within ε=0.10 (>30%)"}
S.append("## Table S8. Calibrated rejection and equivalence tests of the adsorption-only model (120 studies with paired controls; α = 0.05)\n\nPower and equivalence rates are for studies with true reduction share 5–30% (n = 50) or > 30% (n = 51). False equivalence: fraction declared equivalent among studies whose noise-free misfit exceeds the margin; empty when no such study existed. Thresholds, type-I errors and power in this table use the 95th percentile of the 120 paired controls (6 corpora) with a split-half type-I estimate; that calibration did not transfer to new corpora for D1 and is superseded by the conformal, cross-corpus calibration of Table S14 and main-text Table 5. Equivalence and false-equivalence rates do not depend on the rejection threshold.\n\n" + md(e[list(cols)].rename(columns=cols)))
o = pd.read_csv(R + "T_seqver_oc.csv")
ow = o.pivot_table(index="true_over_limit", columns=["rule", "bias_model"], values="p_accept_within_4_rounds").reset_index()
ow.columns = ["true / limit"] + [f"{a} ({b.replace('bias_', '')})" for a, b in ow.columns[1:]]
S.append("## Table S9. Operating characteristic of the sequential verification rules\n\nProbability of accepting a design within four rounds when both true concentrations are at the stated ratio to their limits (20,000 simulated sequences per point, `scripts/seqver_oc.py`; 3% random and 5% calibration error). v2_ratio_n2: duplicates, mean ≤ 0.9·limit; ucb_n3_bonf: triplicates, Bonferroni upper confidence bound ≤ limit.\n\n" + md(ow))
el = pd.read_csv(R + "T_electrolyte_sensitivity.csv")
S.append("## Table S10. Cr(VI) speciation by background electrolyte (minteq.v4; total Cr(VI) 10 mg L⁻¹)\n\n" + md(el))
P = pd.read_csv(R + "T_bench_partition.csv")
S.append("## Table S11. True partition of Cr(VI) disappearance by mechanism scenario (isotherm series, mass-weighted; 3,000 virtual studies per scenario)\n\n`scripts/bench_partition.py`. 'reduced (total)' = dissolved Cr(III) + Cr(III) on solid + precipitate.\n\n" + md(P))
M = pd.read_csv(R + "T_bench_mcse.csv")
S.append("## Table S12. Monte Carlo precision of the mechanism benchmark (R = 100 replicate corpora per scenario)\n\nMCSE = between-replicate SD/√R; R_needed = (1.96·SD/h)² replicates for a 95% half-width h (target_95_halfwidth).\n\n" + md(M))
E = pd.read_csv(R + "T_endpoint_validation.csv")
S.append("## Table S13. Out-of-study accuracy of the four endpoint models (RF, speciation features; 10 corpora; mean over corpora)\n\n`scripts/endpoint_validation.py`. Total-Cr models are trained only on rows with a total-Cr measurement (Class A/B studies; n_studies per corpus). R² and errors on the log₁₀ scale of the modelled transform, and R² on the linear scale.\n\n" + md(E))
import os
if os.path.exists(R + "T_typeI_validation.csv"):
    TI = pd.read_csv(R + "T_typeI_validation.csv")
    keep = ["sd_rel", "design", "typeI_nominal", "typeI_empirical", "typeI_empirical_lo", "typeI_empirical_hi",
            "typeI_conformal", "typeI_conformal_lo", "typeI_conformal_hi", "typeI_loco", "typeI_loco_lo", "typeI_loco_hi",
            "max_corpus_typeI", "thr_conformal_pooled", "power_conformal_pooled|>30%", "power_conformal_pooled|5-30%"]
    S.append("## Table S14. Type-I error of the adsorption-only rejection test on an independent cohort of negative controls\n\n"
             "Columns typeI_nominal, typeI_empirical and typeI_conformal: thresholds from the χ²_ν 95% quantile, the empirical 95th percentile "
             "and the conformal quantile ⌈0.95(n + 1)⌉ of the 120 paired controls (6 corpora), evaluated on 240 independent controls from 12 "
             "new corpora (Wilson 95% intervals). typeI_loco: conformal threshold from 17 of 18 corpora applied to the held-out corpus "
             "(360 controls; corpus-bootstrap 95% interval); max_corpus_typeI: largest held-out-corpus value (20 controls). "
             "thr_conformal_pooled: final threshold from all 360 controls, with power for studies with reduction share > 0.3 and 5–30%. "
             "`scripts/typeI_validation.py`.\n\n" + md(TI[keep]))
S.append("## Fig. S1. Profile likelihoods of the reductant capacity\n\n![Fig. S1](figures/figS1_profiles.png)\n\n**Fig. S1.** Profile of Δ(−2 log L) against log₁₀ R₀ relative to its true value for two virtual studies (true reduction share 0.15 and 0.60) under designs D1, D3 and D4u (D4u: unbiased solid oxidation state). Dotted line: χ²₁ 95% threshold (3.84); symmetric-log axis. Non-smooth peaks indicate local optima at individual profile points; the true profile lies at or below the plotted curve, so the profiles are indicative only. The mechanistic model structure is assumed known.")
open("CASSIA_supplementary.md", "w").write("\n\n".join(S) + "\n")
print("supplement words", len(open("CASSIA_supplementary.md").read().split()))
